insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-3489')::uuid, md5('building-abc-strasse-47-20354')::uuid, '3489', 'neu-saniertes-buerogebaeude-in-bester-city-lage-3489', 'Neu saniertes Bürogebäude in bester City-Lage', 'Das Büro- und Geschäftsgebäude befindet sich in der ABC-Straße nahe dem Gänsemarkt, nur wenige Gehminuten von der Binnenalster und nur wenige Meter von der U-Bahn-Station …', 'Das Büro- und Geschäftsgebäude befindet sich in der ABC-Straße nahe dem Gänsemarkt, nur wenige Gehminuten von der Binnenalster und nur wenige Meter von der U-Bahn-Station Gänsemarkt entfernt. Dieses eindrucksvolle, denkmalgeschützte Bürogebäude aus dem Jahr 1899 vereint historischen Charme mit funktionaler Moderne und bietet Unternehmen eine seltene Gelegenheit zur exklusiven Nutzung.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-3489-1')::uuid, md5('property-3489')::uuid, 'Mietfläche', 1635, 27, null, 'filemaker', '3489-1') on conflict (id) do nothing;
