insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25187')::uuid, md5('building-otto-wels-strasse-49-22297')::uuid, '25187', 'der-stadtpark-turm-zwischen-eppendorf-und-flughafen-mit-grosser-terrasse-25187', 'Der Stadtpark-Turm zwischen Eppendorf und Flughafen mit großer Terrasse', 'Der Stadtpark-Turm befindet sich in unmittelbarer Nähe zum neuen Hamburger Polizeipräsidium. Das Gebäude besticht durch seine moderne Bauform sowie die Nähe zum Hamburger …', 'Der Stadtpark-Turm befindet sich in unmittelbarer Nähe zum neuen Hamburger Polizeipräsidium. Das Gebäude besticht durch seine moderne Bauform sowie die Nähe zum Hamburger Flughafen. Die Anbindung an den ÖPNV ist durch die wenige Meter entfernte U-Bahnstation Alsterdorf als hervorragend zu bezeichnen. Zur Ausstattung gehören ein Hohlraumboden, Teppichboden, ein außenliegender Sonnenschutz, Stehleuchten, bodentiefe Fensterelemente, eine EDV-Verkabelung, eine Pantry sowie getrennte WC-Einheiten. Diese Fläche erstreckt sich vom 9. Obergeschoss bis zum 11. Obergeschoss. Highlight dieser Fläche ist eine ca. 196 qm große Dachterrasse im 11. Obergeschoss mit traumhaften Blick, welche zum oben genannten Mietpreis in die Gesamtmiete mit einfließt. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 236, 1717, 'https://www.buerohamburg.de/objects/pdf/BHI_25187.pdf', null, 'filemaker', '25187') on conflict (id) do nothing;
