insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23889')::uuid, md5('building-ericusspitze-1-20457')::uuid, '23889', 'moderne-bueroflaeche-im-spiegel-haus-in-bester-hafencity-lage-23889', 'Moderne Bürofläche im Spiegel Haus in bester HafenCity-Lage', 'Das imposante Gebäude befindet sich in exponierter Hafen-City-Lage in direkter Nachbarschaft zur historischen Speicherstadt mit Blick auf den Ericusgraben. Das Objekt wurde von …', 'Das imposante Gebäude befindet sich in exponierter Hafen-City-Lage in direkter Nachbarschaft zur historischen Speicherstadt mit Blick auf den Ericusgraben. Das Objekt wurde von dem renommierten dänischen Architekturbüro Henning Larsen entworfen und hat bereits das Umweltzeichen der HafenCity Hamburg GmbH (HCH) in Gold erhalten. Der Rathausmarkt und die zahlreichen Einkaufsstraßen in der Innenstadt sind fußläufig schnell erreicht. Auch die U-Bahnstation Meßberg liegt nur wenige Gehminuten entfernt und sichert einen guten Anschluss an den öffentlichen Nahverkehr. Diverse gastronomische Angebote im direkten Umfeld sorgen für abwechslungsreiche Mittagspausen. Die Ausstattung umfasst unter anderem Wärme- und Lärmschutz durch doppelschalige Glasaußenfassade, natürliche Belüftung über zu öffnende Fenster, Kühlung und Beheizung durch Betonkernaktivierung sowie abgehängte Deckensegeln. Desweiteren ist ein raumweise regelbarer, außenliegender Sonnenschutz und eine EDV-gerechte Beleuchtung mit Stehleuchten vorhanden. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_23889.pdf', null, 'filemaker', '23889') on conflict (id) do nothing;
