insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-391')::uuid, md5('building-eimsbuetteler-strasse-64-22769')::uuid, '391', 'hochwertig-ausgebautes-agentur-buerogebaeude-in-szenelage-391', 'Hochwertig ausgebautes Agentur-/ Bürogebäude in Szenelage', 'Das Bürogebäude befindet sich in zentraler Lage im beliebten Stadtteil Hamburg Altona-Nord, der besonders bei Unternehmen aus der Kreativwirtschaft sehr gefragt ist. Die …', 'Das Bürogebäude befindet sich in zentraler Lage im beliebten Stadtteil Hamburg Altona-Nord, der besonders bei Unternehmen aus der Kreativwirtschaft sehr gefragt ist. Die unmittelbare Nähe zum lebendigen Schanzenviertel sorgt für ein urbanes Umfeld mit zahlreichen gastronomischen, kulturellen und dienstleistungsbezogenen Angeboten. Durch die hervorragende Anbindung an den öffentlichen Nah- und Fernverkehr unter anderem über die nahegelegene S-Bahn-Station Holstenstraße und den Bahnhof Altona sind sowohl die Hamburger Innenstadt als auch das Umland schnell und bequem erreichbar.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-391-1')::uuid, md5('property-391')::uuid, 'Mietfläche', 1774, 16.5, null, 'filemaker', '391-1') on conflict (id) do nothing;
