insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24246')::uuid, md5('building-holstenwall-20-22-20355')::uuid, '24246', 'neustadt-hochwertige-bueroflaeche-mit-gemeinschaftlicher-dachterrasse-24246', 'Neustadt: Hochwertige Bürofläche mit gemeinschaftlicher Dachterrasse', 'Das historische Bürogebäude befindet sich in zentraler Lage der Hamburger Neustadt zwischen der Laeiszhalle und den Wallanlagen Planten un Blomen. Die nahegelegene U-Bahnstationen …', 'Das historische Bürogebäude befindet sich in zentraler Lage der Hamburger Neustadt zwischen der Laeiszhalle und den Wallanlagen Planten un Blomen. Die nahegelegene U-Bahnstationen Messehallen und Gänsemarkt sichern eine gute Anbindung an den ÖPNV. Diverse Cafés und Restaurants sind fußläufig ebenso schnell erreicht wie zahlreiche Einkaufsmöglichkeiten am Gänsemarkt. Die Bürofläche wird in Absprache mit dem zukünftigen Mieter Aufgeteilt und Ausgestattet. Ein Highlight dieser Fläche ist eine große Dachterrasse im 8.OG welche zur gemeinschaftlichen Nutzung für alle Mieter im Haus zur Verfügung steht. Die Fläche erstreckt sich vom Erdgeschoss bis zum 1. Obergeschoss. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'erdgeschoss', 'stellplaetze']::text[], 443, 2012, 'https://www.buerohamburg.de/objects/pdf/BHI_24246.pdf', null, 'filemaker', '24246') on conflict (id) do nothing;
