insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23729')::uuid, md5('building-gasstrasse-6a-22761')::uuid, '23729', 'effiziente-loftflaechen-im-otto-von-bahrenpark-23729', 'Effiziente Loftflächen im Otto von Bahrenpark', 'Das sehr repräsentative Loftgebäude befindet sich im lebendigen Quartier Otto von Bahrenpark, einem Geschäftsquartier der Extraklasse, welches durch seine bunte Mischung aus …', 'Das sehr repräsentative Loftgebäude befindet sich im lebendigen Quartier Otto von Bahrenpark, einem Geschäftsquartier der Extraklasse, welches durch seine bunte Mischung aus Büros, Läden, Arztpraxen Hotels, Restaurants, Fitness- und Freizeitangeboten besticht. Die Anbindung an das öffentliche Verkehrsnetz ist durch diverse Buslinien und die neue S-Bahnstation Ottensen gesichert. Auch die Autobahnauffahrt A7 ist in wenigen Fahrminuten Minuten erreicht. Die Kombination aus traditioneller Backsteinfassade mit moderner Architektur und hochwertiger Flächenausstattung schafft eine besondere Atmosphäre. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23729-1')::uuid, md5('property-23729')::uuid, 'Mietfläche', 2417, 18.95, null, 'filemaker', '23729-1') on conflict (id) do nothing;
