insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23095')::uuid, md5('building-beim-strohhause-17-31-20097')::uuid, '23095', 'helle-bueroflaeche-im-berliner-tor-center-23095', 'Helle Bürofläche im Berliner Tor Center', 'In äußerst verkehrsgünstiger Lage der Hamburger City zwischen der Elbe und der Außenalster befindet sich das markante und weit sichtbare Berliner Tor Center. Das 7-geschossige …', 'In äußerst verkehrsgünstiger Lage der Hamburger City zwischen der Elbe und der Außenalster befindet sich das markante und weit sichtbare Berliner Tor Center. Das 7-geschossige Büro- und Geschäftsgebäude verfügt über ein repräsentatives, gläsernes Foyer sowie zwei Personenaufzüge. Zur Ausstattung der hochwertigen Fläche zählt u. a. ein Hohlraumboden, eine Kühldecke, eine Belüftung sowie ein in die bodentiefen Fensterelemente integrierter Sonnenschutz und getrennte WC-Einheiten. Die Fläche kann den Wünschen des Mieters entsprechend aufgeteilt und ausgebaut werden. Tiefgaragenstellplätze können bei Bedarf angemietet werden. Die Innenbilder stammen aus einer anderen Fläche im Objekt und sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 712, 2564, 'https://www.buerohamburg.de/objects/pdf/BHI_23095.pdf', null, 'filemaker', '23095') on conflict (id) do nothing;
