  (md5('image-24106-2')::uuid, md5('property-24106')::uuid, 'https://www.buerohamburg.de/objects/images/24106/02_webBig.jpg', 'Repräsentatives Büro- und Geschäftsgebäude in erstklassiger Lage – Bild 2', 1, 'filemaker', '24106-02'),
