insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21087')::uuid, md5('building-zirkusweg-4-6-20359')::uuid, '21087', 'st-pauli-hochwertige-bueroflaechen-im-bavaria-office-21087', 'St.Pauli: Hochwertige Büroflächen im Bavaria-Office', 'Das hochmoderne Bürohaus Bavaria Office befindet sich zwischen den Landungsbrücken und dem Hamburger Fischmarkt. Die U-Bahn-Station St. Pauli und diverse Buslinien sichern einen …', 'Das hochmoderne Bürohaus Bavaria Office befindet sich zwischen den Landungsbrücken und dem Hamburger Fischmarkt. Die U-Bahn-Station St. Pauli und diverse Buslinien sichern einen guten Anschluss an den öffentlichen Nahverkehr. Vielseitige Einkaufsmöglichkeiten und zahlreiche Gastronomieangebote erhöhen die Attraktivität dieser urbanen Lage. Die hochwertige Ausstattung der der hellen Büroflächen umfasst unter anderem außen liegenden Sonnenschutz, Hohlraumboden für die Verkabelung, Betonkernaktivierung und teilweise bodentiefe Fenster. Der Mietpreis variiert je nach Lage und Ausstattung im Objekt. Die Innenbilder sind beispielhaft gewählt. Pkw-Stellplätze können nach Rücksprache und Verfügbarkeit in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 912, 2673, 'https://www.buerohamburg.de/objects/pdf/BHI_21087.pdf', null, 'filemaker', '21087') on conflict (id) do nothing;
