insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24788')::uuid, md5('building-ueberseering-33-22297')::uuid, '24788', 'repraesentative-bueroflaeche-im-park-office-in-der-city-nord-24788', 'Repräsentative Bürofläche im Park Office in der City-Nord', 'Das Park Office befindet sich in ruhiger aber zentraler Lage der City-Nord und besticht durch seine goldbedampfte Aluminium-Glas-Fassade. Der Standort überzeugt durch seine gute …', 'Das Park Office befindet sich in ruhiger aber zentraler Lage der City-Nord und besticht durch seine goldbedampfte Aluminium-Glas-Fassade. Der Standort überzeugt durch seine gute Anbindung an den öffentlichen Nahverkehr und den nahegelegenen Flughafen sowie seine Nähe zum Hamburger Stadtpark, der einen hohen Freizeit- und Erholungswert bietet. Im fußläufigen Umfeld befinden sich diverse gastronomische Angebote, die für einen abwechslungsreichen Mittagstisch sorgen. Auch die U-Bahnstation Sengelmannstraße ist nach nur ca. 7 Fußminuten erreicht.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24788-1')::uuid, md5('property-24788')::uuid, 'Mietfläche', 2814, 10, null, 'filemaker', '24788-1') on conflict (id) do nothing;
