insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18649')::uuid, md5('building-gasstrasse-8-16-22761')::uuid, '18649', '12-meter-deckenhoehe-individuelles-loft-im-urbanen-bahrenfeld-18649', '12 Meter Deckenhöhe! Individuelles Loft im urbanen Bahrenfeld', 'Die denkmalgeschützten Conz-Höfe befinden sich inmitten des lebendigen Gewerbeviertels in Bahrenfeld auf dem Gelände des Alten Gaswerkes in unmittelbarer Nähe der S-Bahnstation …', 'Die denkmalgeschützten Conz-Höfe befinden sich inmitten des lebendigen Gewerbeviertels in Bahrenfeld auf dem Gelände des Alten Gaswerkes in unmittelbarer Nähe der S-Bahnstation Bahrenfeld. Diverse gastronomische Angebote im direkten Umfeld erhöhen die Attraktivität dieser urbanen Stadtteillage. Die geräumige Erdgeschoss-Loftfläche teilt sich aktuell in ein Großraumbüro, diverse Besprechungsräume, Archiv- und Lagerräume mit CAT-Verkabelung, eine großzügige Küche und separate WC-Einheiten auf. Großzügige Stahl-Fensterfronten, Oberlichter und eine Deckenhöhe von bis zu 12 m sorgen für optimale Belichtung und einen besonderen, industriellen Charme. Kellerräume und Stellplätze können in Absprache angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'erdgeschoss', 'stellplaetze']::text[], 3000, 6000, 'https://www.buerohamburg.de/objects/pdf/BHI_18649.pdf', null, 'filemaker', '18649') on conflict (id) do nothing;
