insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19915')::uuid, md5('building-hermannstrasse-13-20095')::uuid, '19915', 'moderne-bueroflaeche-in-der-europa-passage-19915', 'Moderne Bürofläche in der Europa Passage', 'Das Büro- und Geschäftsgebäude befindet sich in bester Innenstadtlage zwischen Rathausmarkt und Alstertor. Die lebendige Europa Passage mit einer Vielzahl an Geschäften, Cafés und …', 'Das Büro- und Geschäftsgebäude befindet sich in bester Innenstadtlage zwischen Rathausmarkt und Alstertor. Die lebendige Europa Passage mit einer Vielzahl an Geschäften, Cafés und Restaurants ist eine der bekanntesten Einkaufsmeilen Hamburgs. Die Anbindung an den ÖPNV ist durch die U-Bahnstation Rathaus und Jungfernstieg sowie diverse Buslinien sehr gut. Die A1 und A7 sind über die Elbbrücken schnell erreicht. Die Ausstattung sowie die Aufteilung der Flächen variieren und können in Absprache mit dem Vermieter erfolgen. PKW-Stellplätze können im Parkhaus angemietet werden. Die Innenansichten sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 1000, 7771, 'https://www.buerohamburg.de/objects/pdf/BHI_19915.pdf', null, 'filemaker', '19915') on conflict (id) do nothing;
