insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24063')::uuid, md5('building-saseler-damm-39a-22395')::uuid, '24063', 'moderne-bueroflaeche-in-zentraler-lage-von-poppenbuettel-24063', 'Moderne Bürofläche in zentraler Lage von Poppenbüttel', 'Das gepflegte Büro- und Geschäftsgebäude befindet sich in ruhiger aber zentraler Lage von Poppenbüttel. Das direkte Umfeld ist geprägt durch zahlreiche Cafés und Restaurants. Das …', 'Das gepflegte Büro- und Geschäftsgebäude befindet sich in ruhiger aber zentraler Lage von Poppenbüttel. Das direkte Umfeld ist geprägt durch zahlreiche Cafés und Restaurants. Das in direkter Nachbarschaft gelegene Alstertaler Einkaufszentrum sorgt für Zugang zu allen Geschäften des täglichen Bedarfs sowie einem breiten gastronomischen Angebot. Der Bus- und S-Bahnhof Poppenbüttel liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung an das öffentliche Verkehrsnetz. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24063-1')::uuid, md5('property-24063')::uuid, 'Mietfläche', 3699, 12.5, null, 'filemaker', '24063-1') on conflict (id) do nothing;
