insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24952')::uuid, md5('building-hammerbrookstrasse-5-20097')::uuid, '24952', 'arbeiten-in-hamburg-hammerbrook-moderne-bueroflaeche-mit-befristung-24952', 'Arbeiten in Hamburg-Hammerbrook – moderne Bürofläche mit Befristung', 'Das markante Büro- und Geschäftsgebäude befindet sich in zentraler Citylage nahe der U- und S-Bahnstation Berliner Tor. Nach wenigen Schritten erreicht man ein großes Real-Center …', 'Das markante Büro- und Geschäftsgebäude befindet sich in zentraler Citylage nahe der U- und S-Bahnstation Berliner Tor. Nach wenigen Schritten erreicht man ein großes Real-Center mit Zugang zu zahlreichen Geschäften des täglichen Bedarfs sowie diversen gastronomischen Angeboten. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24952-1')::uuid, md5('property-24952')::uuid, 'Mietfläche', 3870, 9.5, null, 'filemaker', '24952-1') on conflict (id) do nothing;
