insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25109')::uuid, md5('building-deelboegenkamp-4-22297')::uuid, '25109', 'moderne-bueroflaeche-im-alsterpark-25109', 'Moderne Bürofläche im Alsterpark', 'Das 2019 modernisierte, ruhige und doch zentral gelegene Gewerbeobjekt befindet sich in unmittelbarer Nähe zum Alsterlauf in bevorzugter Stadtteillage in Alsterdorf. Eine sehr …', 'Das 2019 modernisierte, ruhige und doch zentral gelegene Gewerbeobjekt befindet sich in unmittelbarer Nähe zum Alsterlauf in bevorzugter Stadtteillage in Alsterdorf. Eine sehr gute Anbindung an die Innenstadt und den nahe gelegenen Flughafen ist durch die U-Bahnstation Lattenkamp und diverse Bushaltestellen gesichert. Auch die Autobahnen A7, A23, A24 und die A1 sind in wenigen Fahrminuten erreicht. Die Bürofläche erschließt sich über moderne Eingangsbereiche mit zwei Personenaufzügen. Auf dem Areal befindet sich außerdem eine von allen Mietern nutzbare Kantine. Die Aufteilung und Ausstattung der Fläche erfolgt in Absprache mit dem zukünftigen Mieter. Der Mietpreis variiert je nach den individuellen Ausbauwünschen. PKW-Stellplätze stehen in der hauseigenen Tiefgarage sowie auf den Hofgelände zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 427, 3925, 'https://www.buerohamburg.de/objects/pdf/BHI_25109.pdf', null, 'filemaker', '25109') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25109-1')::uuid, md5('property-25109')::uuid, 'Mietfläche', 3925, 16.5, null, 'filemaker', '25109-1') on conflict (id) do nothing;
