insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24634')::uuid, md5('building-weidestrasse-118-a-c-22083')::uuid, '24634', 'barmbek-effiziente-und-moderne-bueroflaeche-in-der-alstercity-24634', 'Barmbek: Effiziente und moderne Bürofläche in der AlsterCity', 'Inmitten der lebendigen Hamburger Stadtteile Winterhude und Barmbek-Süd liegt die AlsterCity – ein moderner, etablierter Bürostandort mit urbanem Flair und naturnaher Umgebung. In …', 'Inmitten der lebendigen Hamburger Stadtteile Winterhude und Barmbek-Süd liegt die AlsterCity – ein moderner, etablierter Bürostandort mit urbanem Flair und naturnaher Umgebung. In dem Gebäudeteil stehen moderne Büroflächen zur Verfügung, die sich flexibel an unterschiedliche Nutzungskonzepte anpassen lassen. Großzügige Fensterfronten sorgen für helle, freundliche Arbeitsbereiche, ergänzt durch zusätzliche Lagerflächen sowie Stellplätze in der Tiefgarage und im Außenbereich.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24634-1')::uuid, md5('property-24634')::uuid, 'Mietfläche', 4003, 14, null, 'filemaker', '24634-1') on conflict (id) do nothing;
